// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 fuzzyTimestamp, uint256 fuzzyBlockNum, address actor) public {
        vm.assume(actor != address(0));
        uint256 amount = 10 ether;

        uint256 ts = bound(fuzzyTimestamp, 1, type(uint64).max);
        uint256 bn = bound(fuzzyBlockNum, 1, 10_000_000);

        vm.deal(actor, amount);

        vm.warp(ts);
        vm.roll(bn);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");

        uint256 recordedAfterFirst = c.pastBlockTime();

        vm.warp(ts);
        vm.roll(bn);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");

        uint256 recordedAfterSecond = c.pastBlockTime();

        if (ok1) {
            assertTrue(recordedAfterFirst == ts);
        } else {
            assertTrue(recordedAfterFirst == 0);
        }
    }
}
